namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly string[] _templates =
    [
        "New comment on your post",
        "Your build succeeded",
        "Deployment completed",
        "New pull request review",
        "Issue assigned to you",
        "Release v{0} published",
        "Security alert resolved",
        "Team member joined the project",
        "Scheduled maintenance reminder",
        "Workflow run completed"
    ];

    public Task<List<NotificationItem>> GetInitialNotificationsAsync()
    {
        var notifications = new List<NotificationItem>();
        for (int i = 0; i < 3; i++)
        {
            notifications.Add(CreateNotification());
        }
        return Task.FromResult(notifications);
    }

    public Task<List<NotificationItem>> CheckForNewNotificationsAsync()
    {
        // Simulate: ~40% chance of a new notification each poll
        var results = new List<NotificationItem>();
        if (Random.Shared.Next(5) < 2)
        {
            results.Add(CreateNotification());
        }
        return Task.FromResult(results);
    }

    private NotificationItem CreateNotification()
    {
        var id = _nextId++;
        var template = _templates[Random.Shared.Next(_templates.Length)];
        var message = string.Format(template, id);
        return new NotificationItem
        {
            Id = id,
            Message = message,
            Timestamp = DateTime.Now
        };
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (Items is not null)
    {
        <span class="badge bg-primary ms-2">@Items.Count</span>
    }
</h1>

@if (Items is null)
{
    <p><em>Loading notifications...</em></p>
}
else if (Items.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in Items)
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<NotificationItem>? Items { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only fetch when state wasn't restored from prerender
        Items ??= await NotificationSvc.GetInitialNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender is never called during prerender,
            // so the polling loop only starts once the page is interactive.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
                var newItems = await NotificationSvc.CheckForNewNotificationsAsync();
                if (newItems.Count > 0)
                {
                    Items ??= new();
                    Items.InsertRange(0, newItems);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

